function updateHud(){if(!run)return;$('clock').textContent=`${String(Math.floor(run.t/60)).padStart(2,'0')}:${String(Math.floor(run.t%60)).padStart(2,'0')}`;$('kills').textContent=run.kills;$('gold').textContent=run.shards;$('level').textContent=`LEVEL ${run.level} · ${Math.floor(run.xp)} / ${run.next} XP`;$('xpbar').style.width=`${Math.min(100,run.xp/run.next*100)}%`;$('hpbar').style.width=`${clamp(run.p.hp/run.p.maxHp*100,0,100)}%`;const bar=$('weapons');bar.innerHTML='';for(const [id,l] of Object.entries(run.weapons)){const d=weapons[id],el=document.createElement('div');el.className='weapon-icon';el.title=d.name;el.innerHTML=`${d.icon}<b>${l}</b>`;bar.append(el)}}
const worldColors=['#222521','#292520','#242322','#272421'];
function spawnEnemy(){const p=run.p,angle=rand(0,Math.PI*2),radius=Math.max(W(),H())*.67+rand(20,100),x=p.x+Math.cos(angle)*radius,y=p.y+Math.sin(angle)*radius;let elapsed=run.t,roll=Math.random(),type=elapsed>100&&roll<.28?'wraith':elapsed>35&&roll<.48?'brute':'ghoul';if(run.t>240&&roll<.14)type='shade';const spec={ghoul:[13,22,30,1.2,'#82916d'],brute:[19,75,18,.72,'#a35c4f'],wraith:[12,33,42,1.45,'#8778a4'],shade:[10,28,58,1.72,'#9b7895'] }[type];run.pool.push({x,y,r:spec[0],hp:spec[1]*(1+elapsed/300),max:spec[1]*(1+elapsed/300),speed:spec[2]*(1+elapsed/240),damage:spec[3],color:spec[4],type,phase:rand(0,6),hit:0})}
function spawnBoss(){const a=Math.random()*Math.PI*2,p=run.p;run.boss={x:p.x+Math.cos(a)*Math.max(W(),H())*.6,y:p.y+Math.sin(a)*Math.max(W(),H())*.6,r:34,hp:950,max:950,speed:30,attack:2.5,hit:0};run.bossSpawned=true;$('bossbar').style.display='block';toast('THE GRAVEKEEPER HAS FOUND YOU')}
function addGem(x,y,value=1){run.gems.push({x,y,value,r:value>1?6:4,spin:rand(0,6)})}
function killEnemy(e){run.kills++;run.shards+=Math.max(1,Math.floor(run.stats.greed*(e.type==='brute'?3:1)));addGem(e.x,e.y,e.type==='brute'?2:1);for(let i=0;i<5;i++)run.particles.push({x:e.x,y:e.y,vx:rand(-60,60),vy:rand(-60,60),life:rand(.2,.6),color:e.color,size:rand(2,4)});}
function hurt(e,damage){if(e.hp<=0)return;e.hp-=damage;e.hit=.12;if(e.hp<=0){if(e===run.boss){run.boss=null;$('bossbar').style.display='none';run.shards+=60;for(let i=0;i<18;i++)addGem(e.x+rand(-30,30),e.y+rand(-30,30),2);toast('THE GRAVEKEEPER FALLS · +60 SHARDS')}else killEnemy(e)}}
function nearest(){let best=null,d=Infinity;for(const e of run.pool){const q=dist(run.p,e);if(q<d){best=e;d=q}}if(run.boss){let q=dist(run.p,run.boss);if(q<d){best=run.boss;d=q}}return best}
function attack(dt){let p=run.p, haste=1+run.stats.haste;for(const [id,level] of Object.entries(run.weapons)){let w=weapons[id];w.cool-=dt*haste;if(id==='ember'){let count=1+Math.floor((level-1)/2);if(!w.orbs)w.orbs=[];while(w.orbs.length<count)w.orbs.push(rand(0,6.28));for(let n=0;n<count;n++){w.orbs[n]+=dt*(2.2+level*.12);const x=p.x+Math.cos(w.orbs[n])*(38+level*4),y=p.y+Math.sin(w.orbs[n])*(38+level*4);for(const e of run.pool)if(Math.hypot(e.x-x,e.y-y)<e.r+10)hurt(e,dt*(25+level*14)*(1+run.stats.might));if(run.boss&&Math.hypot(run.boss.x-x,run.boss.y-y)<run.boss.r+12)hurt(run.boss,dt*(28+level*13)*(1+run.stats.might))}}else if(w.cool<=0){let target=nearest();if(!target)continue;if(id==='bolt'){w.cool=Math.max(.22,1.12-level*.13);let dmg=(25+level*23)*(1+run.stats.might);hurt(target,dmg);run.effects.push({type:'bolt',x1:p.x,y1:p.y,x2:target.x,y2:target.y,life:.17,color:'#b9eaff'});for(let i=0;i<Math.floor(level/3);i++){let other=run.pool.filter(e=>e!==target).sort((a,b)=>dist(a,target)-dist(b,target))[0];if(other){hurt(other,dmg*.55);run.effects.push({type:'bolt',x1:target.x,y1:target.y,x2:other.x,y2:other.y,life:.15,color:'#aaa8ff'})}}}if(id==='blade'){w.cool=Math.max(.3,1.4-level*.12);let a=Math.atan2(target.y-p.y,target.x-p.x),length=58+level*13;run.effects.push({type:'slash',x:p.x,y:p.y,a,length,life:.23});for(const e of run.pool)if(dist(e,p)<length+e.r&&Math.abs(Math.atan2(Math.sin(Math.atan2(e.y-p.y,e.x-p.x)-a),Math.cos(Math.atan2(e.y-p.y,e.x-p.x)-a)))<.7)hurt(e,(44+level*28)*(1+run.stats.might));if(run.boss&&dist(run.boss,p)<length+run.boss.r)hurt(run.boss,(44+level*28)*(1+run.stats.might))}if(id==='frost'){w.cool=Math.max(1.3,4.2-level*.42);let radius=90+level*17;run.effects.push({type:'ring',x:p.x,y:p.y,r:radius,life:.45});for(const e of run.pool)if(dist(e,p)<radius+e.r){hurt(e,(28+level*20)*(1+run.stats.might));e.slow=.9}if(run.boss&&dist(run.boss,p)<radius+run.boss.r)hurt(run.boss,(28+level*20)*(1+run.stats.might))}}}}
function levelUpCheck(){while(run.xp>=run.next){run.xp-=run.next;run.level++;run.next=Math.floor(run.next*1.24+3);levelUp();break}}
function update(dt){if(!run||state!=='play')return;run.t+=dt;run.elapsedFrame++;let p=run.p;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+touchVec.x,dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+touchVec.y,len=Math.hypot(dx,dy);if(len>1){dx/=len;dy/=len}p.x+=dx*p.speed*dt;p.y+=dy*p.speed*dt;if(dx)p.face=Math.sign(dx);p.invuln=Math.max(0,p.invuln-dt);run.shake=Math.max(0,run.shake-dt*18);
let spawnInterval=Math.max(.23,1.25-run.t*.0018);run.spawn-=dt;if(run.spawn<=0){spawnEnemy();if(run.t>70&&Math.random()<.42)spawnEnemy();run.spawn=spawnInterval}if(run.t>=270&&!run.bossSpawned)spawnBoss();if(run.t>=360){finish(true);return}
for(let i=run.pool.length-1;i>=0;i--){let e=run.pool[i];if(e.hp<=0){run.pool.splice(i,1);continue}let d=dist(e,p)||1,slow=e.slow||0;e.slow=Math.max(0,slow-dt);let sp=e.speed*(slow?0.35:1);e.x+=(p.x-e.x)/d*sp*dt;e.y+=(p.y-e.y)/d*sp*dt;e.phase+=dt*3;e.hit=Math.max(0,e.hit-dt);if(d<p.r+e.r&&p.invuln<=0){p.hp-=e.damage;p.invuln=.55;run.shake=5;for(let k=0;k<8;k++)run.particles.push({x:p.x,y:p.y,vx:rand(-70,70),vy:rand(-70,70),life:.4,color:'#d95150',size:3});if(p.hp<=0){finish(false);return}}}
if(run.boss){let b=run.boss,d=dist(b,p)||1;b.x+=(p.x-b.x)/d*b.speed*dt;b.y+=(p.y-b.y)/d*b.speed*dt;b.attack-=dt;b.hit=Math.max(0,b.hit-dt);if(d<p.r+b.r&&p.invuln<=0){p.hp-=18;p.invuln=.7;run.shake=8}if(b.attack<=0){b.attack=2.7;for(let i=0;i<3;i++){let a=Math.atan2(p.y-b.y,p.x-b.x)+(i-1)*.34;run.shots.push({x:b.x,y:b.y,vx:Math.cos(a)*125,vy:Math.sin(a)*125,r:7,life:3})}}if(p.hp<=0){finish(false);return}$('bossfill').style.width=`${Math.max(0,b.hp/b.max*100)}%`}
for(let i=run.shots.length-1;i>=0;i--){let s=run.shots[i];s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;if(Math.hypot(s.x-p.x,s.y-p.y)<p.r+s.r&&p.invuln<=0){p.hp-=12;p.invuln=.6;s.life=0;run.shake=6}if(s.life<=0)run.shots.splice(i,1)}
attack(dt);for(let i=run.gems.length-1;i>=0;i--){let g=run.gems[i],d=dist(g,p);g.spin+=dt*3;if(d<125*run.stats.magnet){let k=(1-d/(125*run.stats.magnet));g.x+=(p.x-g.x)*dt*(2+10*k);g.y+=(p.y-g.y)*dt*(2+10*k)}if(d<p.r+g.r+5){run.xp+=g.value;run.gems.splice(i,1);levelUpCheck();if(state!=='play')break}}
for(let i=run.particles.length-1;i>=0;i--){let q=run.particles[i];q.x+=q.vx*dt;q.y+=q.vy*dt;q.life-=dt;if(q.life<=0)run.particles.splice(i,1)}for(let i=run.effects.length-1;i>=0;i--){run.effects[i].life-=dt;if(run.effects[i].life<=0)run.effects.splice(i,1)}if(run.elapsedFrame%8===0)updateHud()}

